import React, { useState, useEffect } from 'react';
import axios from 'axios';
import Navbar from '../components/Navbar'; // Assuming Navbar component exists
import Footer from '../components/Footer'; // Assuming Footer component exists
import FAQPage from '../components/FAQPage'; // Assuming FAQPage component exists

// Function to fetch download options from the backend for an Instagram URL
const fetchInstagramDownloadOptions = async (url) => {
  // Basic URL validation
  if (!url || !url.trim()) {
    throw new Error('Please enter an Instagram video, reel, or IGTV URL.');
  }

  // Basic validation if it looks like an Instagram URL
  if (!url.includes('instagram.com/p/') && !url.includes('instagram.com/reel/') && !url.includes('instagram.com/tv/')) {
     throw new Error('Please enter a valid Instagram post, reel, or IGTV URL.');
  }

  try {
    // Make a GET request to the backend endpoint for Instagram options
    // Assumes your backend has an endpoint like '/get-instagram-options'
    const response = await axios.get('http://localhost:5000/get-instagram-options', {
      params: { url },
    });

    // Check if the backend response has the expected structure
    // Instagram might return just one option or multiple depending on the post type
    if (response.data && Array.isArray(response.data.options) && typeof response.data.thumbnailUrl !== 'undefined') {
      return response.data;
    } else {
      // Log unexpected response structure for debugging
      console.error('Backend response has unexpected structure:', response.data);
      throw new Error('Received unexpected data from the server.');
    }

  } catch (error) {
    // Log the full error for debugging
    console.error('Error fetching Instagram download options:', error);
    // Provide a user-friendly error message
    throw new Error(
      error.response?.data?.message || // Use backend error message if available
      error.message || // Use standard error message
      'Failed to fetch download options from server.' // Generic fallback
    );
  }
};


function IGDownloader() {
  // State for the video URL input
  const [videoUrl, setVideoUrl] = useState('');
  // State for dark mode toggle
  const [darkMode, setDarkMode] = useState(false);
  // State to indicate loading status
  const [isLoading, setIsLoading] = useState(false);
  // State to store and display errors
  const [error, setError] = useState(null);
  // State to store the fetched download options (different formats/qualities)
  const [downloadOptions, setDownloadOptions] = useState([]);
  // State to store the video thumbnail URL
  const [thumbnailUrl, setThumbnailUrl] = useState('');

  // Effect to load dark mode preference from local storage on component mount
  useEffect(() => {
    const isDarkMode = localStorage.getItem('darkMode') === 'true';
    setDarkMode(isDarkMode);
    // Apply dark mode class to the document element
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, []); // Empty dependency array means this effect runs only once on mount

  // Function to toggle dark mode
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);
    // Save dark mode preference to local storage
    localStorage.setItem('darkMode', newDarkMode);
    // Apply/remove dark mode class
    if (newDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  };

  // Handler for input change
  const handleInputChange = (event) => {
    setVideoUrl(event.target.value);
    // Clear any previous error, options, or thumbnail when input changes
    if (error) {
      setError(null);
    }
    if (downloadOptions.length > 0) {
      setDownloadOptions([]);
    }
    if (thumbnailUrl) {
      setThumbnailUrl(null);
    }
  };

  // Handler for the main download button click
  const handleDownload = async () => {
    // Clear previous state and set loading to true
    setError(null);
    setDownloadOptions([]);
    setThumbnailUrl(null);
    setIsLoading(true);

    try {
      // Call the function to fetch download options from the backend
      const data = await fetchInstagramDownloadOptions(videoUrl);
      // Update state with fetched options and thumbnail URL
      setDownloadOptions(data.options);
      setThumbnailUrl(data.thumbnailUrl);

      console.log('Frontend: Thumbnail URL set to:', data.thumbnailUrl); // Log for debugging

    } catch (err) {
      // Set error state if fetching fails
      setError(err.message || 'An unexpected error occurred.');
      // Clear options and thumbnail on error
      setDownloadOptions([]);
      setThumbnailUrl(null);
    } finally {
      // Set loading to false when the process finishes
      setIsLoading(false);
    }
  };

  // Handler for clicking a specific download option button
  const handleDownloadFile = (url, format = 'mp4', quality = 'video') => {
    // Sanitize quality and format for filename
    const safeQuality = String(quality || 'video').toLowerCase();
    const safeFormat = String(format || 'mp4').toLowerCase();

    // Suggest a filename based on quality and format
    const suggestedFilename = `instagram_video_${safeQuality}.${safeFormat}`;
    // Construct the backend download URL
    // Assumes your backend has an endpoint like '/download-instagram-file'
    const backendDownloadUrl = `http://localhost:5000/download-instagram-file?url=${encodeURIComponent(url)}&filename=${encodeURIComponent(suggestedFilename)}`;

    // Redirect the browser to the backend download URL to initiate download
    window.location.href = backendDownloadUrl;
  };

  return (
    // Main container with dynamic background and text color based on dark mode
    <div className={`min-h-screen bg-zinc-100 dark:bg-zinc-800 text-zinc-900 dark:text-zinc-200 flex flex-col items-center transition-colors duration-300`}>

      {/* Navbar component */}
      <Navbar
        darkMode={darkMode}
        toggleDarkMode={toggleDarkMode}
      />

      {/* Main content area */}
      <div className="flex-grow w-full flex justify-center">
        <div className="flex flex-col items-center py-10 px-4 w-full">
          {/* Header section */}
          <header className="text-center mb-8 mt-8 px-4">
            <h1 className="text-4xl md:text-5xl font-bold text-blue-600 dark:text-blue-400 mb-4">
              Instagram Video Downloader
            </h1>
            <p className="text-xl md:text-2xl text-zinc-700 dark:text-zinc-300">
              Download your favorite Instagram videos, reels, and IGTV easily and for free.
            </p>
          </header>

          {/* Main content card */}
          <main className="w-full max-w-xl bg-white dark:bg-zinc-900 rounded-lg shadow-md dark:shadow-lg p-6 md:p-8 mx-4">
            {/* Input field for video URL */}
            <div className="mb-6">
              <label htmlFor="videoUrl" className="block text-lg font-medium text-zinc-800 dark:text-zinc-200 mb-2">
                Paste Instagram Video/Reel/IGTV URL here:
              </label>
              <input
                type="text"
                id="videoUrl"
                className="w-full px-4 py-3 rounded-md border border-zinc-300 dark:border-zinc-600 bg-zinc-50 dark:bg-zinc-700 text-zinc-900 dark:text-zinc-100 placeholder-zinc-500 dark:placeholder-zinc-400 focus:outline-none focus:ring-2 focus:ring-blue-500 dark:focus:ring-blue-400 focus:border-blue-500 dark:focus:border-blue-400 transition-colors duration-300"
                placeholder="https://www.instagram.com/reel/..." // Updated placeholder
                value={videoUrl}
                onChange={handleInputChange}
                disabled={isLoading}
              />
            </div>

            {/* Download button */}
            <button
              onClick={handleDownload}
              className="w-full bg-blue-600 hover:bg-blue-700 dark:bg-blue-700 dark:hover:bg-blue-600 text-white font-bold py-3 px-4 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-opacity-50 transition-colors duration-300 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
              disabled={isLoading || !videoUrl.trim()}
            >
              {/* Loading spinner and text */}
              {isLoading ? (
                <>
                  <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                  </svg>
                  Processing...
                </>
              ) : (
                'Get Download Options'
              )}
            </button>

            {/* Error message display */}
            {error && (
              <div className="mt-4 p-3 bg-red-100 dark:bg-red-900 border border-red-400 dark:border-red-700 text-red-700 dark:text-red-300 rounded-md text-center">
                {error}
              </div>
            )}

            {/* Thumbnail display */}
            {console.log(thumbnailUrl)}
            {thumbnailUrl && (
              <div className="mt-6 text-center">
                <img
                  src={thumbnailUrl}
                  alt="Video Thumbnail"
                  className="mx-auto rounded-md shadow-sm max-w-full h-auto"
                  // Fallback image if thumbnail fails to load
                  onError={(e) => {
                    console.error('Frontend: Thumbnail image failed to load:', e);
                    e.target.onerror = null; // Prevent infinite loop
                    e.target.src = 'https://placehold.co/400x225/E5E7EB/1F2937?text=No+Thumbnail'; // Placeholder
                  }}
                />
              </div>
            )}

            {/* Display download options */}
            {downloadOptions.length > 0 && (
              <div className="mt-6 border-t border-zinc-200 dark:border-zinc-700 pt-6">
                <h2 className="text-xl font-semibold text-zinc-700 dark:text-zinc-300 mb-4 text-center">Available Downloads:</h2>
                <div className="space-y-3 flex flex-col">
                  {/* Filter and map through download options */}
                  {downloadOptions
                    // Basic filter to exclude options that might be separators or invalid
                    .filter(option => option.url && !String(option.quality).includes('--') && !String(option.format).includes('--'))
                    .map((option, index) => (
                      <button
                        key={index}
                        onClick={() => handleDownloadFile(option.url, option.format, option.quality)}
                        className="block bg-green-500 hover:bg-green-600 dark:bg-green-600 dark:hover:bg-green-500 text-white font-medium py-3 px-4 rounded-md text-center no-underline transition duration-150 ease-in-out"
                      >
                        Download {option.format.toUpperCase()} - {option.quality} {option.size ? `(${option.size})` : ''}
                      </button>
                    ))}
                </div>
                 {/* Download tip */}
                <p className="text-xs text-zinc-500 dark:text-zinc-400 mt-4 text-center">
                  Tip: If clicking the button doesn't work, try right-clicking and selecting "Save link as...".
                </p>
              </div>
            )}

            {/* Initial message when no options are displayed */}
            {!isLoading && !error && downloadOptions.length === 0 && !thumbnailUrl && (
              <div className="mt-6 text-center text-zinc-500 dark:text-zinc-400 text-sm">
                <p>Enter the full URL of the Instagram video, reel, or IGTV you want to download.</p>
                <p className="mt-2 text-xs">Please ensure you have the necessary permissions to download the video. Downloads are intended for personal offline use only.</p>
              </div>
            )}
          </main>
          {/* FAQ Page component */}
          <FAQPage />
        </div>
      </div>
      {/* Footer component */}
      <Footer/>
    </div>
  );
}

export default IGDownloader;
